    public static IServiceCollection AddLedgerModule(this IServiceCollection services)
    {
        services.AddSingleton<IModuleManifestProvider, LedgerModuleManifestProvider>();
        services.AddSingleton<LedgerRepository>();
        services.AddSingleton<LedgerOperationsRepository>();
        services.AddSingleton<LedgerSetupRepository>();
        services.AddSingleton<LedgerMappingConfigurationRepository>();
        services.AddSingleton<LedgerUxRepository>();
        services.AddSingleton<LedgerConfigurationCache>();
        services.AddSingleton<LedgerService>();
        services.AddSingleton<LedgerPreviewService>();
        services.AddSingleton<LedgerPreviewRepository>();
        services.AddSingleton<LedgerTransactionCapability>();
        services.AddSingleton<ITransactionalLedgerPostingCapability>(sp => sp.GetRequiredService<LedgerTransactionCapability>());
        services.AddSingleton<ITransactionalPaymentLedgerPostingCapability>(sp => sp.GetRequiredService<LedgerTransactionCapability>());
        services.AddSingleton<ITransactionalInvoiceLedgerPostingCapability>(sp => sp.GetRequiredService<LedgerTransactionCapability>());
        services.AddSingleton<ITransactionalInventoryLedgerPostingCapability>(sp => sp.GetRequiredService<LedgerTransactionCapability>());
        services.AddSingleton<ITransactionalFixedAssetLedgerPostingCapability>(sp => sp.GetRequiredService<LedgerTransactionCapability>());
        services.AddSingleton<ILedgerPostingEngine>(provider => provider.GetRequiredService<LedgerService>());
        services.AddSingleton<ILedgerControlBalanceRead>(provider => provider.GetRequiredService<LedgerService>());
        services.AddSingleton<ILedgerAccountingWorkspaceCapabilities>(provider => provider.GetRequiredService<LedgerService>());
        return services;
    }

